"""Synonyms for the instant search: words customers type that the catalogue does not use.

Two sources, merged (the manual file wins):
  * ai_search/synonyms.json - edited by the shop owner, e.g. {"sk": {"kombinezón": ["overal"]}}
  * automatic list generated by Claude (cheap Haiku call) from the catalogue's own phrases,
    cached in DATA_DIR/synonyms_<lang>.json and refreshed when the catalogue changes or weekly.
"""
import hashlib
import json
import logging
import os
import time

log = logging.getLogger("ai_search.synonyms")

MANUAL_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "synonyms.json")
MAX_AGE_DAYS = 7


def load_manual(lang, path=None):
    try:
        with open(path or MANUAL_PATH, encoding="utf-8") as f:
            data = json.load(f)
    except (FileNotFoundError, ValueError) as e:
        if not isinstance(e, FileNotFoundError):
            log.warning("synonyms.json is not valid JSON: %s", e)
        return {}
    out = {}
    for customer, targets in (data.get(lang) or {}).items():
        if isinstance(targets, str):
            targets = [targets]
        out[customer] = [t for t in targets if isinstance(t, str) and t.strip()]
    return out


def _cache_path(data_dir, lang):
    return os.path.join(data_dir, f"synonyms_{lang}.json")


def load_auto(data_dir, lang):
    try:
        with open(_cache_path(data_dir, lang), encoding="utf-8") as f:
            return json.load(f)
    except (FileNotFoundError, ValueError):
        return None


def merged(data_dir, lang):
    """{customer phrase: [catalogue phrases]} - automatic list overridden by the manual file."""
    out = {}
    auto = load_auto(data_dir, lang)
    for item in (auto or {}).get("items", []):
        out.setdefault(item["customer"], []).append(item["catalog"])
    out.update(load_manual(lang))
    return out


def ensure_auto(data_dir, lang, index, ai):
    """Generate the automatic synonyms when missing, stale, or the catalogue's phrases changed."""
    if ai is None or not getattr(ai, "enabled", False):
        return False
    phrases = sorted({ph for ph, _ in index.phrases})
    digest = hashlib.sha256("\n".join(phrases).encode()).hexdigest()[:16]
    cached = load_auto(data_dir, lang)
    if cached and cached.get("phrases_hash") == digest and time.time() - cached.get("generated_at", 0) < MAX_AGE_DAYS * 86400:
        return False
    items = ai.synonyms(lang, phrases)
    if not items:
        return False
    os.makedirs(data_dir, exist_ok=True)
    tmp = _cache_path(data_dir, lang) + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump({"phrases_hash": digest, "generated_at": int(time.time()), "items": items}, f, ensure_ascii=False, indent=1)
    os.replace(tmp, _cache_path(data_dir, lang))
    log.info("generated %d synonyms for %s", len(items), lang)
    return True
